result:
Ya tengo el contexto necesario: `host.ts` declara `AgentHostBindings` sin los tres creadores de mensaje que `contracts.ts` y `agentHostBindings.ts` sí implementan; los dos sitios de `host()` en `stopHooksCore.ts` heredan ese tipo incompleto. Propongo ampliarlo localmente sin tocar `host.ts`.

```json
{"file": "src/packages/agent/internal/stopHooksCore.ts",
 "edits": [
   {"old": "import { getAgentHostBindings } from '../host.js'
import type { HostTask, StopHookExecutionResult } from '../host.js'",
    "new": "import { getAgentHostBindings } from '../host.js'
import type { AgentHostBindings, HostTask, StopHookExecutionResult } from '../host.js'"},
   {"old": "type StopHookResult = {
  blockingErrors: AgentMessage[]
  preventContinuation: boolean
}",
    "new": "type StopHookResult = {
  blockingErrors: AgentMessage[]
  preventContinuation: boolean
}

/**
 * `AgentHostBindings` (declarado en `../host.ts`) aún no cablea los
 * creadores de mensaje que este pipeline invoca — existen en la fuente
 * (`contracts.ts`) y en el binding real (`agentHostBindings.ts`), pero su
 * declaración en `../host.ts` quedó corta. Se amplía aquí, local a este
 * archivo, sin tocar `../host.ts`.
 */
type StopHookHostBindings = AgentHostBindings & {
  createUserMessage?: (opts: { content: string; isMeta?: boolean }) => AgentMessage
  createSystemMessage?: (content: string, level?: string) => AgentMessage
}"},
   {"old": "  const hookStartTime = Date.now()
  const host = () => getAgentHostBindings()",
    "new": "  const hookStartTime = Date.now()
  const host = (): StopHookHostBindings => getAgentHostBindings()"},
   {"old": "async function* hooksDeTeammate(
  permissionMode: string,
  toolUseContext: AgentToolUseContext,
): AsyncGenerator<unknown, StopHookResult> {
  const host = () => getAgentHostBindings()",
    "new": "async function* hooksDeTeammate(
  permissionMode: string,
  toolUseContext: AgentToolUseContext,
): AsyncGenerator<unknown, StopHookResult> {
  const host = (): StopHookHostBindings => getAgentHostBindings()"}
 ],
 "patterns": [
   {"patron": "agent-host-bindings-missing-message-creators",
    "senal_del_verificador": "TS2339: Property 'create(?:User|System|UserInterruption)Message' does not exist on type 'AgentHostBindings'",
    "fix_generico": "El tipo `AgentHostBindings` de `host.ts` no declara `createUserMessage`/`createSystemMessage`/`createUserInterruptionMessage`, aunque `contracts.ts` y el binding real (`agentHostBindings.ts`) sí los tienen. Sin tocar `host.ts`, en el archivo consumidor se importa `AgentHostBindings` como tipo, se declara localmente una intersección `AgentHostBindings & { <método>?: <firma exacta de contracts.ts> }` y se anota con ella el retorno de la función/constante `host`/`host()` que hace de fachada — no hace falta `as`, porque los campos añadidos son opcionales y la asignación es estructuralmente válida.",
    "edits": [0, 1, 2, 3]}
 ],
 "fixes": [
   "src/packages/agent/internal/stopHooksCore.ts(508,24): error TS2339: Property 'createSystemMessage' does not exist on type 'AgentHostBindings'.",
   "src/packages/agent/internal/stopHooksCore.ts(651,36): error TS2339: Property 'createUserMessage' does not exist on type 'AgentHostBindings'."
 ],
 "skipped": []}
```
